1	/**
2	 * RAINBOW game: one connected 3D world, one continuous route.
3	 *   intro  (01–02)  real-time cinematic: the girl drops the towel bundle (Benny hidden) into Drum A,
4	 *                   closes the door and walks away; Benny peeks, then the spin tumbles him down the drain.
5	 *   ride   (03–10)  interactive: auto-propelled along the course, steer left/right, real coin pickups,
6	 *                   5 hearts (bumping the foam walls costs one), pause/resume.
7	 *   outro  (11)     real-time victory cinematic: Benny is hidden under the towel; the SAME girl opens the
8	 *                   door, folds/holds the towel without ever seeing him; FINAL SPIN COMPLETE.
9	 * window.__rainbow exposes a deterministic QA API used by scripts/capture.mjs.
10	 */
11	import * as THREE from 'three';
12	import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
13	import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
14	import { UnrealBloomPass } from 'three/examples/jsm/postprocessing/UnrealBloomPass.js';
15	import { OutputPass } from 'three/examples/jsm/postprocessing/OutputPass.js';
16	import { Course, StageId, WORLD } from '../world/course';
17	import { buildEnvironment } from '../world/environment';
18	import { createCandyEnvironment, createRenderer } from '../render/env';
19	import { createGradePass } from '../render/grade';
20	import { createHud } from '../ui/hud';
21	import { findCinematic, playCinematic } from '../ui/cinematicVideo';
22	import { createCoins, COIN_VALUE } from '../gameplay/coins';
23	import { createInput } from '../gameplay/input';
24	import { RideCamera } from './cameraRig';
25	import { flag05 } from '../vfx/waterRibbon';
26	import { MATCH } from './match';
27	import { buildMatch08 } from '../world/match08';
28	import { loadBennyRuntime, loadGirlRuntime, loadWater, moduleStatus } from './modules';
29	
30	type Mode = 'intro' | 'ride' | 'outro' | 'end';
31	const START_COINS = 1330;
32	const STAGE_ORDER: StageId[] = ['01', '02', '03', '04', '05', '06', '07', '08', '09', '10', '11'];
33	const sm = (a: number, b: number, x: number) => THREE.MathUtils.smoothstep(x, a, b);
34	const lerp = THREE.MathUtils.lerp;
35	
36	/** intro timeline marks (seconds) */
37	const T = { dropEnd: 1.6, doorClose0: 1.9, doorClose1: 2.8, walk0: 3.0, peek: 4.4, cp01: 6.6, spin: 7.4, cp02: 9.1, drain: 11.4, rideStart: 14.0 };
38	/** outro timeline marks */
39	const O = { hide: 0.6, walk0: 0.0, door0: 1.1, door1: 2.1, lean0: 1.9, fold0: 2.7, fold1: 3.7, hold: 6.4, badge: 3.9, cp11: 5.2 };
40	
41	export async function startGame(canvas: HTMLCanvasElement) {
42	  const qs = new URLSearchParams(location.search);
43	  const qaMode = qs.has('qa');
44	  const renderer = createRenderer(canvas, { preserveDrawingBuffer: qaMode });
45	  const dpr = qs.has('dpr') ? Number(qs.get('dpr')) : Math.min(window.devicePixelRatio || 1, 2);
46	  renderer.setPixelRatio(dpr);
47	  const scene = new THREE.Scene();
48	  scene.environment = createCandyEnvironment(renderer);
49	  scene.background = new THREE.Color('#b23fb4');
50	  const fog = new THREE.FogExp2('#ffbde9', 0.0035);
51	  scene.fog = fog;
52	  scene.add(new THREE.HemisphereLight('#fff0ff', '#a33bb8', 1.15));
53	  const sun = new THREE.DirectionalLight('#fff4e6', 1.6);
54	  sun.position.set(0.3, 1, 0.45);
55	  scene.add(sun);
56	  scene.add(sun.target);
57	  const fill = new THREE.PointLight('#ffd8ff', 30, 30, 1.6);
58	  scene.add(fill);
59	
60	  const camera = new THREE.PerspectiveCamera(66, 9 / 16, 0.05, 1200);
61	  const composer = new EffectComposer(renderer);
62	  composer.addPass(new RenderPass(scene, camera));
63	  // Screen 05 test GL1 (user 2026-11-16: "the glow on the highlights is most of what makes the approved version look so
64	  // shiny"): `?glow05=1` = a stronger UnrealBloom with a HIGH threshold, so only the bright highlights (streak cores,
65	  // flares, lamps) glow. Tuning without a rebuild: ?bloomS= (strength) ?bloomR= (radius) ?bloomT= (threshold, linear
66	  // HDR luminance). Switch off: 0.2 / 0.35 / 0.94 exactly as before (pixel-identical default build).
67	  const glow05 = flag05('glow05');
68	  const flowPlan = flag05('flowplan'); // user's Google Flow plan: videos 01–03 + 09–11, playable 04–08 (see startFlowEnding)
69	  const qn = (k: string, d: number) => { const v = qs.get(k); return v !== null && v !== '' && isFinite(+v) ? +v : d; };
70	  // (measured 2026-11-16, qa/pilot05/wave12/glow/: threshold 1.0–1.3 washed the whole river toward white — the scene's
71	  // linear HDR body colours pass it; 2.6 keeps only streak cores, flares and lamps → water saturation UP, 0.92 → 0.97)
72	  const bloom = new UnrealBloomPass(new THREE.Vector2(256, 256), qn('bloomS', glow05 ? 1.0 : 0.2), qn('bloomR', glow05 ? 0.4 : 0.35), qn('bloomT', glow05 ? 2.6 : 0.94));
73	  // Tone-mapping test TM1 (same message: "use NoToneMapping or lower the exposure"): `?tone05=none` → NoToneMapping,
74	  // `?tone05=0.75` → Neutral at that exposure. The OutputPass tone-maps the whole frame (not per material), so this is
75	  // global by nature. Off: Neutral 0.86 (src/render/env.ts), unchanged.
76	  const tone05 = qs.get('tone05');
77	  if (tone05 === 'none') renderer.toneMapping = THREE.NoToneMapping;
78	  else if (tone05 !== null && tone05 !== '' && isFinite(+tone05) && +tone05 > 0) renderer.toneMappingExposure = +tone05;
79	  const useBloom = qs.get('bloom') !== '0';
80	  if (useBloom) composer.addPass(bloom);
81	  composer.addPass(new OutputPass());
82	  composer.addPass(createGradePass());
83	
84	  const resize = () => {
85	    const w = canvas.clientWidth || window.innerWidth;
86	    const h = canvas.clientHeight || window.innerHeight;
87	    renderer.setSize(w, h, false);
88	    composer.setSize(w, h);
89	    bloom.resolution.set(w / 2, h / 2);
90	    camera.aspect = w / h;
91	    camera.updateProjectionMatrix();
92	  };
93	  window.addEventListener('resize', resize);
94	  resize();
95	
96	  // ---------------------------------------------------------------- world
97	  const course = new Course();
98	  const env = buildEnvironment(course);
99	  scene.add(env.group);
100	  const water = await loadWater(course);
101	  scene.add(water.group);
102	  const benny = await loadBennyRuntime();
103	  scene.add(benny.root);
104	  const girl = await loadGirlRuntime();
105	  const coins = createCoins(course);
106	  scene.add(coins.group);
107	  // `?match08=1`: the approved Screen 08 scenery on fitted 3D geometry (src/world/match08.ts); off: nothing is built
108	  const m08 = MATCH['08'] ? await buildMatch08() : null;
109	  if (m08) { m08.group.visible = false; scene.add(m08.group); m08.bakeDepth(renderer); scene.add(m08.splash); }
110	  const M08_HIDE = ['ribbon', 'foam', 'bubbles', 'splashCrown', 'spray'];
111	  // `?match08=1` Benny on Screen 08 toward the approved picture: smaller beanie, body a little higher out of the water,
112	  // white-and-purple knit stripes (crown tint); everything restored when leaving 08 (qa/match/08/NOTES.md)
113	  const M08_BENNY = { hat: 0.86, lift: 0.06, dx: 0.26, body: [0.94, 1.0, 0.94] as const, crown: new THREE.Color().setRGB(0.86, 1.04, 1.0) };
114	  const b08 = m08 ? { hat: benny.root.getObjectByName('hat'), body: benny.root.getObjectByName('body'), aux: benny.root.getObjectByName('AuxScene'), crown: benny.root.getObjectByName('hat_crown') as THREE.Mesh | undefined } : null;
115	  const b08Rest = b08 ? { hat: b08.hat?.scale.x ?? 1, body: (b08.body?.scale ?? new THREE.Vector3(1, 1, 1)).clone(), pos: (b08.aux?.position ?? new THREE.Vector3()).clone(), y: b08.aux?.position.y ?? 0, crown: ((b08.crown?.material as THREE.MeshStandardMaterial | undefined)?.color ?? new THREE.Color()).clone() } : null;
116	  let m08On = false;
117	  let m08Applied = false;
118	  // debug: ?hide=water,benny,coins,drumA,basin,tubes,chamber
119	  const hidden = new Set((qs.get('hide') ?? '').split(',').filter(Boolean));
120	  if (hidden.has('water')) water.group.visible = false;
121	  if (hidden.has('coins')) coins.group.visible = false;
122	  const zoneHidden = (k: string) => hidden.has(k);
123	  const hud = createHud();
124	  const input = createInput(canvas);
125	  const rideCam = new RideCamera(course);
126	  rideCam.axis = env.tubeAxis;
127	
128	  // ---------------------------------------------------------------- state
129	  const st = {
130	    mode: 'intro' as Mode,
131	    t: 0, // time within the current mode
132	    clock: 0, // global animation time (shaders)
133	    frozen: null as number | null, // QA: freeze shader time
134	    s: 0,
135	    lat: 0,
136	    vlat: 0,
137	    coins: START_COINS,
138	    hearts: 5,
139	    paused: false,
140	    stage: '01' as StageId,
141	    bumpCooldown: 0,
142	    edgeTime: 0,
143	    twirl: 0,
144	    respawns: 0,
145	    log: [] as { t: number; s: number; y: number; stage: StageId }[],
146	  };
147	
148	  const stageOf = (s: number): StageId => course.stageAtS(s).id;
149	
150	  const setStage = (id: StageId) => {
151	    if (st.stage === id) return;
152	    st.stage = id;
153	    hud.setStage(id);
154	    updateZones();
155	  };
156	
157	  const zoneRanges: Record<keyof typeof env.zones, [StageId, StageId]> = {
158	    drumA: ['01', '02'],
159	    basin: ['02', '05'],
160	    tubes: ['03', '09'],
161	    chamber: ['07', '11'],
162	  };
163	  const updateZones = () => {
164	    const i = STAGE_ORDER.indexOf(st.stage);
165	    for (const [k, [a, b]] of Object.entries(zoneRanges)) {
166	      env.zones[k as keyof typeof env.zones].visible = !zoneHidden(k) && i >= STAGE_ORDER.indexOf(a) && i <= STAGE_ORDER.indexOf(b);
167	    }
168	    if (m08) { m08On = st.stage === '08'; m08.group.visible = m08On; if (m08On) env.zones.chamber.visible = false; }
169	    const inDrum = i <= 1;
170	    fog.density = inDrum ? 0.0015 : i >= 7 ? 0.0025 : 0.0035;
171	  };
172	
173	  // girl placement helpers (she lives in laundry-room local frames)
174	  const placeGirl = (room: 'A' | 'C', local: THREE.Vector3, yaw: number) => {
175	    const anchor = room === 'A' ? env.roomA.anchor : env.roomC.anchor;
176	    if (girl.root.parent !== anchor) anchor.add(girl.root);
177	    girl.root.position.copy(local);
178	    girl.root.rotation.set(0, yaw, 0);
179	  };
180	
181	  const bennyPose = (s: number, lat: number, time: number, out: { pos: THREE.Vector3; quat: THREE.Quaternion }) => {
182	    const f = course.sample(s);
183	    const h = water.surfaceHeight(s, lat, time);
184	    out.pos.copy(f.pos).addScaledVector(f.right, lat).addScaledVector(f.up, h + benny.radius * 0.55);
185	    const m = new THREE.Matrix4().makeBasis(new THREE.Vector3().crossVectors(f.up, f.tan).normalize(), f.up, f.tan);
186	    out.quat.setFromRotationMatrix(m);
187	    return f;
188	  };
189	
190	  const pose = { pos: new THREE.Vector3(), quat: new THREE.Quaternion() };
191	  const tmpV = new THREE.Vector3();
192	  const wakeAnchor = new THREE.Vector3(); // VFX: Benny's lifted body centre fed to water.wake()
193	  const doorAOpen = -1.9, doorCOpen = -1.95;
194	
195	  // ---------------------------------------------------------------- intro (01–02)
196	  const introUpdate = (dt: number) => {
197	    const t = st.t;
198	    const wc = (water as unknown as { controls?: { drumSwirl: number; drumAgitation: number; outro: number } }).controls;
199	    if (wc) {
200	      wc.drumAgitation = 0.35 + 0.65 * sm(T.spin - 0.5, T.spin + 0.8, t);
201	      wc.drumSwirl = sm(T.spin, T.spin + 1.2, t) * (1 - sm(T.drain + 0.5, T.rideStart, t));
202	      wc.outro = 0;
203	    }
204	    const dA = WORLD.drumA;
205	    const start = course.sample(0).pos;
206	    // --- girl: drop the load, close the door, walk away at normal pace (never looks back)
207	    const spots = env.roomA.spots;
208	    if (t < T.walk0) {
209	      placeGirl('A', new THREE.Vector3(1.2, spots.nearDoor.y, 7.6), Math.PI);
210	      girl.play(t < T.dropEnd ? 'dropLoad' : 'closeDoor', { fade: 0.25 });
211	    } else {
212	      const k = THREE.MathUtils.clamp((t - T.walk0 - 0.35) / 4.6, 0, 1);
213	      const from = new THREE.Vector3(1.2, spots.nearDoor.y, 7.6);
214	      const p = from.clone().lerp(spots.exitLeft, k);
215	      const dir = spots.exitLeft.clone().sub(from);
216	      const yawWalk = Math.atan2(dir.x, dir.z);
217	      const turn = sm(T.walk0, T.walk0 + 0.6, t);
218	      placeGirl('A', p, lerp(Math.PI, yawWalk, turn));
219	      girl.play('walk', { fade: 0.3 });
220	    }
221	    // --- door A
222	    env.doorA.rotation.y = lerp(doorAOpen, 0, sm(T.doorClose0, T.doorClose1, t));
223	    // --- towel bundle flies from her hands into the drum, Benny hidden inside
224	    const handW = girl.handR.getWorldPosition(tmpV).clone();
225	    const k = sm(0.35, T.dropEnd, t);
226	    const towelRest = start.clone().add(new THREE.Vector3(0.15, -1.25, 0.05));
227	    const arc = handW.clone().lerp(towelRest, k);
228	    arc.y += Math.sin(k * Math.PI) * 1.2;
229	    let sB = 0;
230	    if (t >= T.spin && st.stage === '01') { st.stage = '02'; hud.setStage('02'); }
231	    if (t < T.spin) {
232	      env.drumTowel.mesh.position.copy(t < 0.35 ? handW : arc);
233	      env.drumTowel.mesh.rotation.set(0, 0.4, 0);
234	      env.drumTowel.setBundle(1);
235	      env.drumTowel.mesh.scale.setScalar(0.62);
236	      // Benny inside the bundle; peeks out only once she has turned away
237	      const peek = sm(T.peek, T.peek + 0.7, t);
238	      benny.root.visible = peek > 0.02;
239	      benny.setExpression('peek');
240	      bennyPose(0, 0, st.clock, pose);
241	      benny.root.position.copy(start).add(new THREE.Vector3(0, -1.0 + 1.35 * peek, 0));
242	      benny.root.quaternion.setFromEuler(new THREE.Euler(0, Math.PI + 0.25, 0)); // facing the camera (inside drum)
243	      benny.update(dt, { swim: 0, steer: 0, speed: 0, time: st.clock });
244	    } else {
245	      // spin: tumble along the 02 helix, then the chute
246	      const u = sm(T.spin, T.rideStart, t);
247	      const s03 = course.stage('03').s0;
248	      sB = s03 * (t < T.drain ? 0.55 * sm(T.spin, T.drain, t) : 0.55 + 0.45 * sm(T.drain, T.rideStart, t));
249	      void u;
250	      benny.root.visible = true;
251	      benny.setExpression(t < T.drain + 1.2 ? 'dizzy' : 'happy');
252	      const f = bennyPose(sB, 0, st.clock, pose);
253	      // inside Drum A the swirl carries him along the helix itself (no ribbon surface there yet)
254	      const inDrum = 1 - sm(T.drain - 0.4, T.drain + 0.6, t);
255	      // the swirl lifts him toward the middle of the drum while he tumbles (ref 02), then he drops to the drain
256	      const hp = course.sample(sB).pos;
257	      const toAxis = sm(T.spin, T.spin + 1.0, t) * (1 - sm(T.drain - 1.6, T.drain - 0.2, t)) * 0.45;
258	      hp.x *= 1 - toAxis; hp.y = hp.y + (0.2 - hp.y) * toAxis;
259	      benny.root.position.copy(pose.pos).lerp(hp, inDrum);
260	      const tumble = sm(T.rideStart - 1.0, T.rideStart, t);
261	      // tumble = rolling cartwheels seen by the camera: face the lens, roll around the view axis
262	      const toCam = cam02(benny.root.position).pos.clone().sub(benny.root.position).normalize();
263	      const face = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), toCam);
264	      const roll = new THREE.Quaternion().setFromAxisAngle(toCam, Math.sin(t * 1.7) * 0.9 + t * 1.1);
265	      const wobble = new THREE.Quaternion().setFromEuler(new THREE.Euler(Math.sin(t * 2.3) * 0.35, Math.sin(t * 1.9) * 0.4, 0));
266	      const spinQ = roll.multiply(face).multiply(wobble);
267	      benny.root.quaternion.copy(spinQ).slerp(pose.quat, tumble);
268	      benny.update(dt, { swim: 0.4, steer: 0, speed: 8, time: st.clock, tumble: tumble < 0.99 });
269	      // towel lags behind and unravels in the drum
270	      const sT = Math.max(0, sB - 2.6);
271	      const ft = course.sample(Math.min(sT, course.marks['02_drain'] - 1));
272	      env.drumTowel.mesh.position.copy(ft.pos).addScaledVector(ft.up, -0.4);
273	      env.drumTowel.mesh.rotation.set(t * 0.8, t * 0.5, 0.3);
274	      env.drumTowel.setBundle(lerp(1, 0.45, sm(T.spin, T.cp02, t)));
275	      env.drumTowel.mesh.scale.setScalar(lerp(0.62, 0.8, sm(T.spin, T.cp02, t)));
276	      void f;
277	    }
278	    st.s = sB;
279	    // --- floating laundry
280	    const sw = t < T.spin ? 0 : (t - T.spin) * 1.6;
281	    env.laundry.sock.position.set(Math.cos(2.3 + sw) * 2.2 - 0.6, -1.5 + Math.sin(st.clock * 1.3) * 0.15 + Math.sin(2.3 + sw) * (t < T.spin ? 0 : 1.6), 0.6 - sw * 0.25);
282	    env.laundry.sock.rotation.set(0.3 + sw, 0.6, 0.9 + st.clock * 0.3);
283	    env.laundry.shirt.position.set(-2.0 + Math.cos(0.4 + sw) * (t < T.spin ? 0 : 2.0), -1.6 + Math.sin(st.clock * 1.1 + 1) * 0.15 + (t < T.spin ? 0 : Math.sin(0.4 + sw) * 2.2), 0.9 - sw * 0.2);
284	    env.laundry.shirt.rotation.set(-1.15 + sw * 0.7, 0.2 + sw, 0.15);
285	    env.laundry.shirt.scale.setScalar(0.62);
286	    env.laundry.sock.scale.setScalar(0.62);
287	    // --- cameras
288	    if (t < T.spin + 0.6) {
289	      // 01: inside the drum looking out through the door, Benny peeking in the foreground
290	      camera.position.set(0.85, -1.05, -6.05);
291	      camera.up.set(0, 1, 0);
292	      camera.lookAt(-0.05, -0.2, dA.zDoor);
293	      setFov(64);
294	    } else if (t < T.drain) {
295	      // 02: tumbling with the swirl; the door ring above (deterministic blend from the 01 shot)
296	      const c2 = cam02(benny.root.position);
297	      const k2 = sm(T.spin + 0.6, T.spin + 1.6, t);
298	      const p01 = new THREE.Vector3(0.85, -1.05, -6.05), l01 = new THREE.Vector3(-0.05, -0.2, dA.zDoor);
299	      camera.position.copy(p01.lerp(c2.pos, k2));
300	      camera.up.set(0, 1, 0);
301	      camera.lookAt(l01.lerp(c2.look, k2));
302	      setFov(lerp(64, 68, k2));
303	    } else {
304	      // chute chase cam, blending into the ride camera framing for 03
305	      const kk = sm(T.drain, T.rideStart, t);
306	      const back = course.pointAt(Math.max(0, sB - 3.6), 0, 1.7);
307	      const look = course.pointAt(sB + 4, 0, 0.2);
308	      const rp = new THREE.Vector3(), rt = new THREE.Vector3(), ru = new THREE.Vector3();
309	      rideCam.desired(Math.max(course.stage('03').s0, sB), 0, rp, rt, ru);
310	      camera.position.lerp(back.lerp(rp, kk * kk), 0.15);
311	      camera.up.set(0, 1, 0);
312	      camera.lookAt(look.lerp(rt, kk * kk));
313	      setFov(lerp(66, 64, kk));
314	    }
315	    if (t >= T.rideStart) startRide();
316	  };
317	
318	  /** 02 camera: between Benny and the drum's back wall, looking past him to the door ring */
319	  const cam02 = (b: THREE.Vector3) => {
320	    const dA = WORLD.drumA;
321	    const door = new THREE.Vector3(0, 0.3, dA.zDoor);
322	    const away = b.clone().sub(door).normalize();
323	    const pos = b.clone().addScaledVector(away, 3.0).add(new THREE.Vector3(0, 0.35, 0));
324	    const rr = Math.hypot(pos.x, pos.y);
325	    if (rr > 2.7) { pos.x *= 2.7 / rr; pos.y *= 2.7 / rr; }
326	    pos.y = Math.max(pos.y, dA.waterY + 1.0);
327	    pos.z = THREE.MathUtils.clamp(pos.z, dA.zBack + 0.4, dA.zDoor - 1);
328	    const look = b.clone().lerp(door, 0.22).add(new THREE.Vector3(0, 0.45, 0));
329	    return { pos, look };
330	  };
331	
332	  const setFov = (f: number) => {
333	    if (Math.abs(camera.fov - f) > 0.01) { camera.fov = f; camera.updateProjectionMatrix(); }
334	  };
335	
336	  const startRide = () => {
337	    st.mode = 'ride';
338	    st.t = 0;
339	    st.s = course.stage('03').s0;
340	    st.lat = 0;
341	    hud.setVisible(true);
342	    setStage('03');
343	    rideCam.pos.copy(camera.position);
344	    rideCam.target.copy(camera.position).add(camera.getWorldDirection(new THREE.Vector3()).multiplyScalar(10));
345	    rideCam.fov = camera.fov;
346	    hud.showHint('Drag or hold left / right to steer');
347	    setTimeout(() => hud.showHint(null), 3500);
348	  };
349	
350	  // ---------------------------------------------------------------- ride (03–10)
351	  const rideUpdate = (dt: number) => {
352	    input.update(dt);
353	    const stg = course.stageAtS(st.s);
354	    const speed = course.prop('speed', st.s);
355	    st.s = Math.min(course.stage('11').s0, st.s + speed * dt);
356	    const halfW = course.widthAt(st.s) / 2;
357	    const safe = halfW - 0.75;
358	    st.vlat += (input.steer * 7.5 - st.vlat) * Math.min(1, dt * 8);
359	    st.lat = THREE.MathUtils.clamp(st.lat + st.vlat * dt, -halfW + 0.55, halfW - 0.55);
360	    // foam-wall bump → lose a heart (with cooldown), bounce back toward the centre
361	    st.bumpCooldown = Math.max(0, st.bumpCooldown - dt);
