738	    /** debug: Benny's projected screen position (NDC -1..1, z<1 = in front of camera) */
739	    bennyScreen() {
740	      const v = benny.root.getWorldPosition(new THREE.Vector3()).project(camera);
741	      return { x: +v.x.toFixed(2), y: +v.y.toFixed(2), z: +v.z.toFixed(3), visible: benny.root.visible, cam: camera.position.toArray().map((q) => +q.toFixed(2)), benny: benny.root.position.toArray().map((q) => +q.toFixed(2)) };
742	    },
743	    /** debug: what does a ray from the camera through NDC (x,y) hit first? */
744	    probe(x = 0, y = 0) {
745	      const rc = new THREE.Raycaster();
746	      rc.setFromCamera(new THREE.Vector2(x, y), camera);
747	      const hits = rc.intersectObjects(scene.children, true).filter((h) => (h.object as THREE.Mesh).isMesh && h.object.visible);
748	      const path = (o: THREE.Object3D) => { const a: string[] = []; let c: THREE.Object3D | null = o; while (c) { a.push(c.name || c.type); c = c.parent; } return a.slice(0, 5).join('<'); };
749	      return hits.slice(0, 4).map((h) => ({ d: +h.distance.toFixed(2), obj: path(h.object), p: h.point.toArray().map((v) => +v.toFixed(2)) }));
750	    },
751	    /** QA: which scene objects issue draw calls in one render ("parent/name" → calls), most first */
752	    drawList() {
753	      const hits = new Map<string, number>();
754	      const hooked: [THREE.Object3D, THREE.Object3D['onAfterRender']][] = [];
755	      scene.traverse((o) => {
756	        if (!(o as THREE.Mesh).isMesh && !(o as THREE.Points).isPoints && !(o as THREE.Line).isLine && !(o as THREE.Sprite).isSprite) return;
757	        const prev = o.onAfterRender;
758	        const key = (o.parent?.name ? o.parent.name + '/' : '') + (o.name || o.type);
759	        hooked.push([o, prev]);
760	        o.onAfterRender = (...a: Parameters<THREE.Object3D['onAfterRender']>) => { hits.set(key, (hits.get(key) ?? 0) + 1); prev.apply(o, a); };
761	      });
762	      render();
763	      for (const [o, prev] of hooked) o.onAfterRender = prev;
764	      return [...hits.entries()].sort((a, b) => b[1] - a[1]);
765	    },
766	    togglePause,
767	    /** QA only (read-only use by scripts/proj05-probe.mjs): the live scene, render camera and renderer, for exact
768	     *  per-pixel river UV / footprint renders. Nothing calls it in the game; rendering is unchanged. */
769	    qa3d() { return { scene, camera, renderer, composer }; },
770	    stats() {
771	      const i = renderer.info;
772	      return { fps: +fps.toFixed(1), calls: i.render.calls, triangles: i.render.triangles, geometries: i.memory.geometries, textures: i.memory.textures, modules: { ...moduleStatus }, courseLength: course.length };
773	    },
774	    course,
775	  };
776	  (window as unknown as { __rainbow: typeof api }).__rainbow = api;
777	  return api;
778	}
