  mesh: THREE.InstancedMesh;
  material: THREE.MeshStandardMaterial;
  uniforms: {
    uTime: { value: number };
    uWind: { value: THREE.Vector3 };
    uMaskCol: { value: THREE.Color };
    uRoot: { value: THREE.Color };
    uTip: { value: THREE.Color };
